import React, { useState, useEffect, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

const ModelLoader = ({ modelPaths, transitionDuration = 6 }) => {
  const groupRef = useRef();
  const [geometries, setGeometries] = useState([]);
  const [morphProgress, setMorphProgress] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);

  useEffect(() => {
    const loader = new OBJLoader();
    const loadedGeometries = [];

    // Load all geometries from provided paths
    Promise.all(
      modelPaths.map(
        (path) =>
          new Promise((resolve) =>
            loader.load(
              `./stls/${path}`,
              (obj) => {
                resolve(extractGeometryFromObject(obj));
              },
              undefined,
              (error) => {
                console.error(`Error loading model ${path}:`, error);
              }
            )
          )
      )
    ).then((geoms) => {
      setGeometries(geoms);
      setIsTransitioning(geoms.length > 1); // Enable transition if more than 1 model
    });
  }, [modelPaths]);

  useFrame((_, delta) => {
    if (isTransitioning && geometries.length > 1) {
      setMorphProgress((prev) => Math.min(prev + delta / transitionDuration, 1));
      if (morphProgress >= 1) {
        setMorphProgress(0);
        setIsTransitioning(false);
      }
    }

    // Rotate the model group slightly
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  // Morph between the first and second geometry
  const morphGeometry =
    geometries.length > 1
      ? morphGeometries(geometries[0], geometries[1], morphProgress)
      : geometries[0];

  return (
    <group ref={groupRef}>
      {morphGeometry && (
        <mesh geometry={morphGeometry}>
          <meshStandardMaterial color="#ff6347" />
        </mesh>
      )}
    </group>
  );
};

// Function to extract geometry from OBJLoader output
function extractGeometryFromObject(obj) {
  let mergedGeometry = new THREE.BufferGeometry();
  obj.traverse((child) => {
    if (child.isMesh) {
      mergedGeometry = child.geometry.clone(); // Return first mesh found
    }
  });
  return mergedGeometry;
}

// Function to interpolate between two geometries
function morphGeometries(geometry1, geometry2, t) {
  const morphGeometry = geometry1.clone();
  const position1 = geometry1.attributes.position.array;
  const position2 = geometry2.attributes.position.array;
  const morphPosition = morphGeometry.attributes.position.array;

  for (let i = 0; i < morphPosition.length; i++) {
    morphPosition[i] = position1[i] + (position2[i] - position1[i]) * t;
  }

  morphGeometry.attributes.position.needsUpdate = true;
  return morphGeometry;
}

export default ModelLoader;
